25	const LinkInternal = forwardRef<HTMLAnchorElement, LinkProps>((props, ref) => {
26	  const { ownProps, restProps, dataAttributes, analytics } = useDefinition(
27	    LinkDefinition,
28	    props,
29	  );
30	  const { classes, title, children } = ownProps;
31	
32	  const internalRef = useRef<HTMLAnchorElement>(null);
33	  const linkRef = (ref || internalRef) as React.RefObject<HTMLAnchorElement>;
34	
35	  const { linkProps } = useLink(restProps, linkRef);
36	  const { isFocusVisible, focusProps } = useFocusRing();
37	  const resolvedHref = useResolvedHref(restProps.href);
38	
39	  const handleClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
40	    linkProps.onClick?.(e);
41	    const text =
42	      restProps['aria-label'] ??
43	      getNodeText(children) ??
44	      String(restProps.href ?? '');
45	    analytics.captureEvent('click', text, {
46	      attributes: { to: String(restProps.href ?? '') },
47	    });
48	  };
49	
50	  return (
51	    <a
52	      {...mergeProps(linkProps, focusProps)}
53	      {...dataAttributes}
54	      {...(restProps as React.AnchorHTMLAttributes<HTMLAnchorElement>)}
55	      href={resolvedHref}
56	      ref={linkRef}
57	      title={title}
58	      className={classes.root}
